func (n *node) lookupFixedPathRedirect(c *Context, trailingSlash bool) bool {
	req := c.Request
	n.redirectPath = req.URL.Path
	n.redirectSlash = trailingSlash
	cleaned := n.canonicalPath(n.redirectPath)
	fixedPath, ok := n.findCaseInsensitivePath(cleaned, n.redirectSlash)
	if !ok {
		return false
	}
	n.assignRedirectTarget(bytesAsString(fixedPath))
	req.URL.Path = n.redirectURL
	n.commitRedirect(c)
	return true
}

func (n *node) prepareRedirectPath(c *Context) {
	if c == nil || c.Request == nil {
		n.redirectPath = "/"
		return
	}
	n.redirectPath = c.Request.URL.Path
	if n.redirectPath == "" {
		n.redirectPath = "/"
	}
}

func (n *node) applyForwardedPrefix(c *Context) {
	if c == nil || c.Request == nil {
		n.redirectPrefix = ""
		return
	}
	prefix := stdpath.Clean(c.Request.Header.Get("X-Forwarded-Prefix"))
	if prefix == "." {
		n.redirectPrefix = ""
		return
	}
	n.redirectPrefix = prefix
	n.redirectPath = n.redirectPrefix + "/" + c.Request.URL.Path
}

func (n *node) toggleTrailingSlash() {
	p := n.redirectPath
	length := len(p)
	if length > 1 && p[length-1] == '/' {
		n.redirectPath = p[:length-1]
		n.redirectSlash = false
		return
	}
	n.redirectPath = p + "/"
	n.redirectSlash = true
}

